import{_ as e,c as l,o as n,a3 as r}from"./chunks/framework.BusRvirq.js";const h=JSON.parse('{"title":"과업 범위 확정 및 요구사항 동결 합의서 (Scope Freeze Sign-off)","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/public/templates/05_Scope_Freeze_Signoff_template.html"}]]},"headers":[],"relativePath":"public/templates/05_Scope_Freeze_Signoff_template.md","filePath":"public/templates/05_Scope_Freeze_Signoff_template.md","lastUpdated":1790810085000}'),a={name:"public/templates/05_Scope_Freeze_Signoff_template.md"};function s(i,t,d,o,g,c){return n(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="과업-범위-확정-및-요구사항-동결-합의서-scope-freeze-sign-off" tabindex="-1">과업 범위 확정 및 요구사항 동결 합의서 (Scope Freeze Sign-off) <a class="header-anchor" href="#과업-범위-확정-및-요구사항-동결-합의서-scope-freeze-sign-off" aria-label="Permalink to “과업 범위 확정 및 요구사항 동결 합의서 (Scope Freeze Sign-off)”">​</a></h1><p>본 문서는 [발주회사명] (이하 &quot;발주처&quot;라 한다)과 주식회사 엠파시 (이하 &quot;수행사&quot;라 한다)가 공동으로 수행 중인 [프로젝트명]의 <strong>Phase 1 (요구사항 분석 및 상세화 단계)</strong> 산출물에 대하여 최종 검토를 마치고, 개발 대상 과업 범위를 공식 확정(Scope Freeze)하기 위해 작성하는 서면 합의서입니다.</p><hr><h3 id="_1-프로젝트-및-검토-개요" tabindex="-1">1. 프로젝트 및 검토 개요 <a class="header-anchor" href="#_1-프로젝트-및-검토-개요" aria-label="Permalink to “1. 프로젝트 및 검토 개요”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">내용</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>사업명</strong></td><td style="text-align:left;">[계약서상 사업명]</td></tr><tr><td style="text-align:left;"><strong>계약 기간</strong></td><td style="text-align:left;">202 년 월 일 ~ 202 년 월 일</td></tr><tr><td style="text-align:left;"><strong>요구사항 분석 기간</strong></td><td style="text-align:left;">202 년 월 일 ~ 202 년 월 일</td></tr><tr><td style="text-align:left;"><strong>확정 대상 산출물</strong></td><td style="text-align:left;">1. 요구사항 정의서 (SRS v1.0, 총 [ ] 건 요구사항)<br>2. 요구사항 추적표 (RTM v1.0, WBS 및 테스트 케이스 매핑)<br>3. BDD 수용 기준 명세서 (Given-When-Then, 총 [ ] 개 시나리오)</td></tr><tr><td style="text-align:left;"><strong>발주처 주관 부서</strong></td><td style="text-align:left;">[현업 주관 부서명 및 IT 정보화 부서명]</td></tr></tbody></table><hr><h3 id="_2-확정-과업-범위-요약-rtm-기준-통계" tabindex="-1">2. 확정 과업 범위 요약 (RTM 기준 통계) <a class="header-anchor" href="#_2-확정-과업-범위-요약-rtm-기준-통계" aria-label="Permalink to “2. 확정 과업 범위 요약 (RTM 기준 통계)”">​</a></h3><p>본 합의에 따라 실제 구현(Phase 2 설계 및 Phase 3 개발) 단계로 진입하는 정량적 과업 내역은 다음과 같습니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">요구사항 분류</th><th style="text-align:center;">제안/RFP 접수 건수</th><th style="text-align:center;">협의/통합 후 확정 건수</th><th style="text-align:center;">범위 제외/차기 이관 건수</th><th style="text-align:left;">비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>시스템 기능 (SFR)</strong></td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:left;">핵심 업무 기능</td></tr><tr><td style="text-align:left;"><strong>데이터 요구사항 (DAR)</strong></td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:left;">데이터 이관 및 연계</td></tr><tr><td style="text-align:left;"><strong>인터페이스 (SIR)</strong></td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:left;">대외/사내 API 연계</td></tr><tr><td style="text-align:left;"><strong>보안 및 규제 (SER)</strong></td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:left;">암호화, 권한 통제</td></tr><tr><td style="text-align:left;"><strong>성능 및 품질 (QUR)</strong></td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:center;">[ ] 건</td><td style="text-align:left;">응답시간, 동시접속자</td></tr><tr><td style="text-align:left;"><strong>합계</strong></td><td style="text-align:center;"><strong>[ ] 건</strong></td><td style="text-align:center;"><strong>[ ] 건</strong></td><td style="text-align:center;"><strong>[ ] 건</strong></td><td style="text-align:left;">-</td></tr></tbody></table><ul><li>[별첨 1] 요구사항 추적표(RTM) 상세 목록 참조.</li></ul><hr><h3 id="_3-과업-범위-동결-scope-freeze-에-관한-4대-핵심-합의-조항" tabindex="-1">3. 과업 범위 동결(Scope Freeze)에 관한 4대 핵심 합의 조항 <a class="header-anchor" href="#_3-과업-범위-동결-scope-freeze-에-관한-4대-핵심-합의-조항" aria-label="Permalink to “3. 과업 범위 동결(Scope Freeze)에 관한 4대 핵심 합의 조항”">​</a></h3><ol><li><strong>과업 범위의 최종성 (Finality of Scope)</strong>: <ul><li>양 당사자는 본 합의서에 명시된 &quot;요구사항 정의서 v1.0&quot; 및 &quot;요구사항 추적표 v1.0&quot;에 등재된 기능과 사양만을 본 사업의 공식 개발 범위로 확정합니다.</li></ul></li><li><strong>구두 요구사항의 무효화 (Ban on Verbal Requests)</strong>: <ul><li>본 합의일 이후 회의, 유선, 이메일, 메신저 등에서 구두로 전달된 추가·변경 요구사항은 계약적 효력을 갖지 않으며, 수행사는 이를 거부하거나 작업을 보류할 수 있습니다.</li></ul></li><li><strong>변경 통제 프로세스 준수 (Mandatory CR Process)</strong>: <ul><li>본 합의 이후 발생하는 모든 요구사항의 추가, 삭제, 사양 변경은 양사 PM의 승인을 거치는 공식 &quot;요구사항 변경 요청서(CR Form)&quot;를 통해서만 접수 및 처리합니다.</li><li>단일 변경 건의 분석 결과 소요 공수가 [ 5 ] M/D 이상이거나 프로젝트 마일스톤에 영향을 미치는 경우, 발주처와 수행사는 계약 금액의 증액 또는 프로젝트 완료일의 연장에 관하여 서면 변경 계약을 체결하여야 합니다.</li></ul></li><li><strong>차기 단계 진입 승인</strong>: <ul><li>발주처는 Phase 1 요구사항 분석 단계의 완료를 공식 확인하며, 수행사가 Phase 2 (아키텍처 및 상세 설계) 단계로 진입하는 것을 정식 승인합니다.</li></ul></li></ol><hr><h3 id="_4-범위-조정-및-특약-사항-제외-및-조건부-반영-항목" tabindex="-1">4. 범위 조정 및 특약 사항 (제외 및 조건부 반영 항목) <a class="header-anchor" href="#_4-범위-조정-및-특약-사항-제외-및-조건부-반영-항목" aria-label="Permalink to “4. 범위 조정 및 특약 사항 (제외 및 조건부 반영 항목)”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">요구사항 ID</th><th style="text-align:left;">요구사항 명칭</th><th style="text-align:center;">조정 내용 (제외 / 조건부)</th><th style="text-align:left;">사유 및 합의 내용</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>SFR-019</strong></td><td style="text-align:left;">[예: AI 자동 세금계산서 OCR]</td><td style="text-align:center;">범위 제외 (차기 고도화)</td><td style="text-align:left;">원천 샘플 데이터 확보 불가로 2차 사업 이관 합의</td></tr><tr><td style="text-align:center;"><strong>SIR-008</strong></td><td style="text-align:left;">[예: 국세청 홈택스 실시간 스크래핑]</td><td style="text-align:center;">조건부 반영</td><td style="text-align:left;">국세청 중계기관 API 제공 시점에 한하여 연동 구현</td></tr></tbody></table><hr><p>위와 같이 프로젝트 요구사항 및 과업 범위가 상호 합의 하에 최종 확정되었음을 확인하며, 본 합의서 2부를 작성하여 양측 책임자가 기명 날인 후 각각 1부씩 보관합니다.</p><p><strong>합의일자: 202 년 월 일</strong></p><p><strong>[발주처]</strong></p><ul><li><p>소속 부서: [현업 주관 부서]</p></li><li><p>직급 / 직책: [ ]</p></li><li><p>성명: [ ] (서명/인)</p></li><li><p>소속 부서: [IT / 정보화 사업 부서]</p></li><li><p>직급 / 직책: [ ]</p></li><li><p>성명: [ ] (서명/인)</p></li></ul><p><strong>[수행사] 주식회사 엠파시</strong></p><ul><li>소속 부서: [프로젝트 수행본부]</li><li>직급 / 직책: [사업 총괄 PM]</li><li>성명: [ ] (서명/인)</li></ul>',23)])])}const x=e(a,[["render",s]]);export{h as __pageData,x as default};
